    def variance_gamma_model(
        self,
        *,
        spot: float,
        strike: float,
        rate: float,
        tau: float,
        sigma: float = 0.2,
        theta: float = -0.1,
        nu: float = 0.2,
        n_simulations: int = 100000,
        option_type: str = "call",
        seed: int = 7,
        greeks: bool = False,
    ) -> dict[str, Any]:
        """Variance Gamma European option price via Monte Carlo.

        Note: the ``theta`` parameter here is the VG skew parameter
        (subordinated-drift), unrelated to the Greek theta (time decay)
        optionally returned when ``greeks=True``.

        Time-changes Brownian motion by a Gamma subordinator (mean 1, variance
        ``nu``). The martingale drift correction ``omega`` is computed in closed
        form so the discounted spot is a martingale.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "spot": spot,
            "strike": strike,
            "rate": rate,
            "tau": tau,
            "sigma": sigma,
            "theta": theta,
            "nu": nu,
            "n_simulations": n_simulations,
            "option_type": option_type,
            "seed": seed,
            "greeks": greeks,
        }
        return self._client._request(
            "POST", "/api/v1/derivatives/variance_gamma_model", json_body=body
        )

    def vasicek_interest_rate_model(
        self,
        *,
        r0: float,
        kappa: float,
        theta: float,
        sigma: float,
        maturity: float,
        n_steps: int = 100,
        n_simulations: int = 50000,
        seed: int = 101,
    ) -> dict[str, Any]:
        """Vasicek model: closed-form zero-coupon bond price + simulated short rate.

        ``dr = κ(θ−r)dt + σ dW``. The affine ZCB price is ``P = A·e^{−B·r0}``. The
        short rate is Gaussian (can go negative).

        Returns:
            The raw API response as a dict.
        """
        body = {
            "r0": r0,
            "kappa": kappa,
            "theta": theta,
            "sigma": sigma,
            "maturity": maturity,
            "n_steps": n_steps,
            "n_simulations": n_simulations,
            "seed": seed,
        }
        return self._client._request(
            "POST", "/api/v1/derivatives/vasicek_interest_rate_model", json_body=body
        )

